//! `chart::settle`: a chart's parts brought to what [`super::generate()`] makes
//! of it at the size it is drawn, keeping each part's id by its role.
//!
//! Derived state, written outside history (`Document::settle_widths`'s pattern):
//! after a commit, an undo, a redo or a load, every [`stale`] chart is
//! regenerated by a transaction of its own that carries `SetChartParts`, the
//! mark `chart::guard` lets write its parts.

use super::{Generated, PartKey, generate};
use crate::document::Document;
use crate::id::{IdSource, NodeId};
use crate::node::NodeKind;
use crate::op::{DirtySet, GeometryPatch, Operation, Transaction};
use crate::resolve::Resolved;
use kurbo::Size;
use rustc_hash::{FxHashMap, FxHashSet};

/// The size `id` is drawn at: its used frame size.
fn drawn_size(doc: &Document, res: &Resolved, id: NodeId) -> Option<Size> {
    match res.used_kind(doc, id)? {
        NodeKind::Artboard { size, .. } => Some(*size),
        _ => None,
    }
}

/// The charts whose parts are out of date: generated for a description since
/// changed, or at another size than the frame is now drawn at. Outside the
/// vault, which is never resolved and never holds a chart.
pub fn stale(doc: &Document, res: &Resolved) -> Vec<NodeId> {
    let mut out: Vec<NodeId> = doc
        .node_map()
        .values()
        .filter_map(|n| {
            let c = n.chart.as_ref()?;
            let size = drawn_size(doc, res, n.id)?;
            let at = [size.width, size.height];
            let fresh = c
                .generated
                .is_some_and(|g| (g[0] - at[0]).abs() < 1e-6 && (g[1] - at[1]).abs() < 1e-6);
            (!fresh).then_some(n.id)
        })
        .collect();
    out.sort();
    out
}

/// The transaction that brings chart `id`'s parts to what it generates at its
/// drawn size, minting ids for new parts from `ids`; `None` when `id` is not a
/// chart. `family` is the document's default text family.
///
/// A chart past its limits ([`super::Refusal`]) keeps the parts it has and is
/// only stamped, so it is not asked again until it changes.
pub fn settle(
    doc: &Document,
    res: &Resolved,
    ids: &mut IdSource,
    id: NodeId,
    family: &str,
) -> Option<Transaction> {
    let node = doc.get(id)?;
    let chart = node.chart.as_ref()?;
    let size = drawn_size(doc, res, id)?;
    let at = Some([size.width, size.height]);
    let Ok(generated) = generate(chart, size, family) else {
        return Some(Transaction(vec![Operation::SetChartParts {
            id,
            parts: chart.parts.clone(),
            at,
        }]));
    };
    Some(Transaction(ops(doc, id, &chart.parts, generated, ids, at)))
}

/// The actor new parts are minted under, past every id the document holds of
/// it: a settle needs no session's id source, so a CLI export or a load
/// regenerates as the app does.
const PART_ACTOR: u64 = 0xC4A2;

/// One round: every stale chart settled against `res` and applied to `doc`
/// directly; the nodes it wrote, for the caller to lay out again.
pub fn settle_round(doc: &mut Document, res: &Resolved) -> DirtySet {
    let mut round = DirtySet::default();
    let charts = stale(doc, res);
    if charts.is_empty() {
        return round;
    }
    let mut ids = IdSource::new(PART_ACTOR);
    crate::document::reserve_existing_ids(doc, &mut ids);
    let family = crate::typography::TextStyle::default().font_family;
    for c in charts {
        let Some(tx) = settle(doc, res, &mut ids, c, &family) else {
            continue;
        };
        // A regeneration the rules refuse leaves the chart as it was: a bug in
        // the generator, never the user's to see as a failed edit.
        match doc.apply(&tx) {
            Ok(outcome) => round.0.extend(outcome.dirty.0),
            Err(e) => debug_assert!(false, "a chart's regeneration was refused: {e}"),
        }
    }
    round
}

/// Every stale chart settled, in rounds until none is left or the rounds run out
/// (a chart in a hugging parent can resize it), `res` laid out again after each.
pub fn settle_all(doc: &mut Document, res: &mut Resolved) -> DirtySet {
    let mut all = DirtySet::default();
    for _ in 0..crate::resolve::MAX_SETTLE_ROUNDS {
        let round = settle_round(doc, res);
        if round.0.is_empty() {
            break;
        }
        res.update(doc, &round);
        all.0.extend(round.0);
    }
    all
}

/// The operations from the chart's current subtree to `generated`.
fn ops(
    doc: &Document,
    chart: NodeId,
    old: &[(PartKey, NodeId)],
    generated: Generated,
    ids: &mut IdSource,
    at: Option<[f64; 2]>,
) -> Vec<Operation> {
    let mut out = Vec::new();
    let under: FxHashSet<NodeId> = crate::build::subtree_nodes(doc, &[chart])
        .into_iter()
        .filter(|n| *n != chart)
        .collect();
    let mut by_key: FxHashMap<PartKey, NodeId> = old
        .iter()
        .filter(|(_, n)| under.contains(n))
        .map(|(k, n)| (*k, *n))
        .collect();
    // A text part whose kind changes is made again under its own id; any other
    // kind is patched. Decided first, so the deletes below take it out.
    let mut remade: FxHashSet<NodeId> = FxHashSet::default();
    for p in &generated.parts {
        if let Some(n) = by_key.get(&p.key).and_then(|n| doc.get(*n))
            && n.kind != p.kind
            && patch(&n.kind, &p.kind).is_none()
        {
            remade.insert(n.id);
        }
    }
    let kept: FxHashSet<NodeId> = generated
        .parts
        .iter()
        .filter_map(|p| by_key.get(&p.key).copied())
        .filter(|n| !remade.contains(n))
        .collect();

    // Delete what no part keeps, topmost first: a deleted frame takes its subtree.
    let mut children: FxHashMap<NodeId, Vec<NodeId>> = FxHashMap::default();
    let mut walk = vec![chart];
    while let Some(p) = walk.pop() {
        let Some(n) = doc.get(p) else { continue };
        let mut list = Vec::new();
        for c in n.children() {
            if kept.contains(c) {
                list.push(*c);
                walk.push(*c);
            } else {
                out.push(Operation::DeleteNode { id: *c });
            }
        }
        children.insert(p, list);
    }
    for id in &remade {
        by_key.retain(|_, n| n != id);
    }

    // Then every part in order: made, moved or patched.
    let mut ids_of: FxHashMap<PartKey, NodeId> = FxHashMap::default();
    let mut placed: FxHashMap<NodeId, usize> = FxHashMap::default();
    for p in &generated.parts {
        let parent = match p.parent {
            Some(k) => match ids_of.get(&k) {
                Some(id) => *id,
                None => continue,
            },
            None => chart,
        };
        let index = *placed.entry(parent).or_insert(0);
        placed.insert(parent, index + 1);
        let existing = by_key.get(&p.key).copied().filter(|n| kept.contains(n));
        let id = match existing {
            Some(id) => {
                let n = doc.get(id).expect("kept parts exist");
                let list = children.entry(parent).or_default();
                if n.parent != Some(parent) {
                    if let Some(old_parent) = n.parent
                        && let Some(l) = children.get_mut(&old_parent)
                    {
                        l.retain(|c| *c != id);
                    }
                    let list = children.entry(parent).or_default();
                    let i = index.min(list.len());
                    list.insert(i, id);
                    out.push(Operation::Reparent {
                        id,
                        new_parent: parent,
                        index: i,
                    });
                } else if list.iter().position(|c| *c == id) != Some(index) {
                    list.retain(|c| *c != id);
                    let i = index.min(list.len());
                    list.insert(i, id);
                    out.push(Operation::Reorder { id, index: i });
                }
                if n.kind != p.kind
                    && let Some(patches) = patch(&n.kind, &p.kind)
                {
                    out.extend(
                        patches
                            .into_iter()
                            .map(|geometry| Operation::SetGeometry { id, geometry }),
                    );
                }
                if n.transform != p.transform {
                    out.push(Operation::SetTransform {
                        id,
                        transform: p.transform,
                    });
                }
                if n.name != p.name {
                    out.push(Operation::SetName {
                        id,
                        name: p.name.clone(),
                    });
                }
                set_rest(&mut out, id, Some(n), p);
                id
            }
            None => {
                let id = ids.mint();
                let list = children.entry(parent).or_default();
                let i = index.min(list.len());
                list.insert(i, id);
                out.push(Operation::CreateNode {
                    id,
                    parent,
                    index: i,
                    kind: p.kind.clone(),
                    transform: Some(p.transform),
                    name: Some(p.name.clone()),
                });
                set_rest(&mut out, id, None, p);
                id
            }
        };
        ids_of.insert(p.key, id);
    }

    let display = Some(generated.display);
    if doc.get(chart).is_some_and(|n| n.display != display) {
        out.push(Operation::SetDisplay { id: chart, display });
    }
    let parts = generated
        .parts
        .iter()
        .filter_map(|p| ids_of.get(&p.key).map(|id| (p.key, *id)))
        .collect();
    out.push(Operation::SetChartParts {
        id: chart,
        parts,
        at,
    });
    out
}

/// The geometry patches taking `from` to `to` where one kind's fields change,
/// `None` where only making it again will do (a text, a change of kind).
fn patch(from: &NodeKind, to: &NodeKind) -> Option<Vec<GeometryPatch>> {
    match (from, to) {
        (NodeKind::Artboard { size: a, .. }, NodeKind::Artboard { size: b, .. }) => {
            Some(if a == b {
                Vec::new()
            } else {
                vec![GeometryPatch::Size(*b)]
            })
        }
        (
            NodeKind::Rect {
                size: a,
                corner_radii: ra,
                ..
            },
            NodeKind::Rect {
                size: b,
                corner_radii: rb,
                ..
            },
        ) => {
            let mut out = Vec::new();
            if a != b {
                out.push(GeometryPatch::Size(*b));
            }
            if ra != rb {
                out.push(GeometryPatch::CornerRadii(*rb));
            }
            Some(out)
        }
        (NodeKind::Ellipse { size: a, .. }, NodeKind::Ellipse { size: b, .. }) => Some(if a == b {
            Vec::new()
        } else {
            vec![GeometryPatch::Size(*b)]
        }),
        (
            NodeKind::Path {
                path: a,
                corner_radii: ra,
                ..
            },
            NodeKind::Path {
                path: b,
                corner_radii: rb,
                ..
            },
        ) => Some(if a == b && ra == rb {
            Vec::new()
        } else {
            vec![GeometryPatch::Path {
                path: b.clone(),
                corner_radii: rb.clone(),
                mirror: None,
            }]
        }),
        _ => None,
    }
}

/// Paint, opacity, layout and a frame's clip, written where `n` (the node as it
/// is, `None` for one just made) differs from `p`.
fn set_rest(out: &mut Vec<Operation>, id: NodeId, n: Option<&crate::Node>, p: &super::Part) {
    let fills = crate::item::keyed_by_position(p.fills.iter().cloned());
    let strokes = crate::item::keyed_by_position(p.strokes.iter().cloned());
    let same = |a: bool| n.is_some() && a;
    if !same(n.is_some_and(|n| n.paint.fills == fills)) && !(n.is_none() && fills.is_empty()) {
        out.push(Operation::SetFills { id, fills });
    }
    if !same(n.is_some_and(|n| n.paint.strokes == strokes)) && !(n.is_none() && strokes.is_empty())
    {
        out.push(Operation::SetStrokes { id, strokes });
    }
    if !same(n.is_some_and(|n| n.opacity == p.opacity)) && !(n.is_none() && p.opacity == 1.0) {
        out.push(Operation::SetOpacity {
            id,
            opacity: p.opacity,
        });
    }
    // A container is unclipped: a label may overflow its axis's box.
    if matches!(p.kind, NodeKind::Artboard { .. }) && n.is_none_or(|n| n.clip) {
        out.push(Operation::SetClip { id, clip: false });
    }
    if n.map_or(p.insets.is_authored(), |n| n.insets != p.insets) {
        out.push(Operation::SetInsets {
            id,
            insets: p.insets,
        });
    }
    if n.map_or(p.display.is_some(), |n| n.display != p.display) {
        out.push(Operation::SetDisplay {
            id,
            display: p.display.clone(),
        });
    }
    if n.map_or(p.item != Default::default(), |n| n.item != p.item) {
        out.push(Operation::SetLayoutItem { id, item: p.item });
    }
}
